#!/usr/bin/env python3
"""Underline all headline paragraphs in the unpacked quarterly report.

Headlines in this report have no heading styles; they are paragraphs whose
entire text is uppercase (e.g., EXECUTIVE SUMMARY, Q1 2025 OUTLOOK). This
script adds <w:u w:val="single"/> to every run-level rPr in those paragraphs,
in schema-valid rPr child order, and skips runs inside deletions.
"""
import os
import xml.dom.minidom as md

WNS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
BASE = os.path.dirname(os.path.abspath(__file__))
DOC_PATH = os.path.join(BASE, "quarterly_unpacked", "word", "document.xml")

# ECMA-376 CT_RPr child order (local names), used to insert w:u legally.
RPR_ORDER = [
    "rStyle", "rFonts", "b", "bCs", "i", "iCs", "caps", "smallCaps", "strike",
    "dstrike", "outline", "shadow", "emboss", "imprint", "noProof",
    "snapToGrid", "vanish", "webHidden", "color", "spacing", "w", "kern",
    "position", "sz", "szCs", "highlight", "u", "effect", "bdr", "shd",
    "fitText", "vertAlign", "rtl", "cs", "em", "lang", "eastAsianLayout",
    "specVanish", "oMath",
]


def elem_children(node):
    return [c for c in node.childNodes if c.nodeType == c.ELEMENT_NODE]


def para_text(p):
    parts = []
    for t in p.getElementsByTagNameNS(WNS, "t"):
        parts.append(t.firstChild.nodeValue if t.firstChild else "")
    return "".join(parts)


def inside_del(node):
    anc = node.parentNode
    while anc is not None:
        if anc.nodeType == anc.ELEMENT_NODE and anc.localName == "del":
            return True
        anc = anc.parentNode
    return False


def underline_run(run):
    rpr = None
    for c in elem_children(run):
        if c.localName == "rPr":
            rpr = c
            break
    if rpr is None:
        rpr = run.ownerDocument.createElementNS(WNS, "w:rPr")
        run.insertBefore(rpr, run.firstChild)
    if any(c.localName == "u" for c in elem_children(rpr)):
        return False
    u = run.ownerDocument.createElementNS(WNS, "w:u")
    u.setAttribute("w:val", "single")
    rank = RPR_ORDER.index("u")
    insert_before = None
    for c in elem_children(rpr):
        if c.localName in RPR_ORDER and RPR_ORDER.index(c.localName) > rank:
            insert_before = c
            break
    if insert_before is not None:
        rpr.insertBefore(u, insert_before)
    else:
        rpr.appendChild(u)
    return True


def main():
    dom = md.parse(DOC_PATH)
    body = dom.getElementsByTagNameNS(WNS, "body")
    if not body:
        raise SystemExit("No w:body found in document.xml")
    paras = 0
    runs = 0
    for p in body[0].getElementsByTagNameNS(WNS, "p"):
        text = para_text(p)
        if not text or not text.isupper():
            continue
        for r in p.getElementsByTagNameNS(WNS, "r"):
            if inside_del(r):
                continue
            if underline_run(r):
                runs += 1
        paras += 1
    if paras:
        with open(DOC_PATH, "wb") as fh:
            dom.writexml(fh, encoding="utf-8")
    print("underlined %d headline paragraph(s), %d run(s)" % (paras, runs))


if __name__ == "__main__":
    main()

